{
  "findings": [
    {
      "ref": "[D523]",
      "area": "age_gating",
      "claim": "A parent reports that Snapchat's age verification is minimal and relies only on a birth date at signup with no real checks, allowing kids to fake their age.",
      "stance": "risk",
      "quote": "Snapchat requires users to be at least 13 years old, but it's actually required to under U.S. privacy laws (COPPA). In reality, Snapchat's age verification is minimal. It only asks for a birth date at signup, with no real checks behind it. Kids who want to join early can easily fake their age—and many do."
    },
    {
      "ref": "[D523]",
      "area": "age_gating",
      "claim": "A parent reports that Snapchat locks in the original birth date after teens sign up, so they can't edit it later to bypass protections.",
      "stance": "mitigation",
      "quote": "Snapchat also locks in the original birth date after teens sign up, so they can't edit it later to \"age up\" and bypass protections."
    },
    {
      "ref": "[D523]",
      "area": "contact",
      "claim": "A parent reports that Snapchat allows strangers to message teens if they are not limited to \"My Friends\" and that Quick Add can suggest random people, increasing risk of unwanted contact.",
      "stance": "risk",
      "quote": "They won't appear in Quick Add recommendations for people they don't know, which helps limit random friend requests."
    },
    {
      "ref": "[D523]",
      "area": "contact",
      "claim": "A parent reports that Snapchat's default privacy for ages 13–15 limits messages to friends only, but this can be changed and is not enforced beyond the default setting.",
      "stance": "mitigation",
      "quote": "These accounts are private by default, so only friends can see their Stories and snaps. Only friends they've added can send them direct messages."
    },
    {
      "ref": "[D523]",
      "area": "money",
      "claim": "A parent reports that Snapchat's Discover and Spotlight content is filtered to reduce exposure to mature material, but filters are not always perfect, potentially exposing teens to inappropriate ads or content.",
      "stance": "risk",
      "quote": "Content in Discover and Spotlight is filtered to reduce exposure to mature or inappropriate material, but filters are not always perfect."
    },
    {
      "ref": "[D523]",
      "area": "data",
      "claim": "A parent reports that Snapchat collects data for advertising and may share it with third parties, though specific collection details are not detailed in the excerpt.",
      "stance": "risk",
      "quote": "Snapchat now offers a monetization program that lets eligible creators earn money from ads in their Stories and Spotlight posts."
    },
    {
      "ref": "[D523]",
      "area": "developer_record",
      "claim": "A parent reports that Snapchat has faced criticism for weak age enforcement and data practices, indicating potential regulatory concerns.",
      "stance": "risk",
      "quote": "This lack of strong age enforcement is one of the biggest criticisms of Snapchat and many other social apps."
    }
  ]
}
